const neck=azHull([W3(shA+.02,.07,shZ+.08),W3(shA+.02,-.07,shZ+.08),W3(shA+.10,.06,shZ-.05),W3(shA+.10,-.06,shZ-.05),
W3(hA-.02,.05,hZ+.03),W3(hA-.02,-.05,hZ+.03),W3(hA-.02,.05,hZ-.07),W3(hA-.02,-.05,hZ-.07)].map(p=>HH.p(...p)));
