{const [x,y]=H.p(...AZ_COIL,.02);for(let k=0;k<4;k++){const E=ell(x,y-k*1.8,17-k*2.2,7.5-k*1);H.line(R,E.concat([E[0]]),'teal',2.2,{tone:.62,amp:.05});H.line(R,E.concat([E[0]]),'blue',.5,{tone:.5,amp:.05})}}

