/* ---- the cat on the radiator ---- */
function drawCat(H,R,u){
const [cx,cy]=H.p(AT.cat[0],AT.cat[1],.745);
const br=.5-.5*Math.cos(TAU*u/4),look=W.cat(u);
const flick=bump(1.2,1.9,u)+bump(6.1,6.7,u)+bump(15.4,16.0,u)+.6*bump(18.3,18.8,u);
const T=P=>rotPts(sc(P,cx,cy,1.25),cx,cy,.32);
H.tint(T(ell(cx+1,cy+1,14,3.4)),'blue',.26);
const tail=T(curve([[cx-11,cy-1],[cx-13,cy+2.5],[cx-7,cy+4.4],[cx,cy+4.6],[cx+4+flick*3,cy+3.6-flick*4.5]],2));
H.line(R,tail,'blue',5.2,{tone:.9,amp:.05});H.line(R,tail,'paper',3.6,{tone:1,amp:.05});
H.line(R,tail,'sun',3.6,{tone:.62,amp:.05});H.line(R,tail,'coral',3.6,{tone:.30,amp:.05});
const body=T(loop([[cx-12,cy+.5],[cx-11,cy-6-br*.5],[cx-3,cy-9.4-br*.8],[cx+6,cy-8.2-br*.5],[cx+11,cy-3],[cx+9.5,cy+1.8],[cx-8,cy+2.4]],2));
H.fill(body,'sun',.64);H.tint(body,'coral',.30);
for(const [a,b] of[[-6,-7.5],[-2,-8.6],[2,-8.2]])H.line(R,T([[cx+a,cy+b-br*.6],[cx+a+1.5,cy+b+4]]),'coral',1,{tone:.6,amp:.1});
H.outline(R,body,'blue',1,{tone:.9,amp:.12});
const hx=cx+10+look*1.2,hy=cy-5.5-look*4.2;
const head=T(ell(hx,hy,4.8,4.2,16));
H.fill(head,'sun',.64);H.tint(head,'coral',.30);H.outline(R,head,'blue',.9,{tone:.9,amp:.08});
for(const E of[T([[hx-3.8,hy-2],[hx-2.6,hy-7.4-look*1.2],[hx-.4,hy-3.8]]),T([[hx+.4,hy-3.9],[hx+2.8,hy-7.6-look*1.2],[hx+4.2,hy-1.8]])]){
H.fill(E,'sun',.64);H.tint(E,'coral',.42);H.outline(R,E,'blue',.8,{tone:.9,amp:.05})}
if(look>.5)for(const dx of[-1.8,1.6]){const p=T([[hx+dx,hy-.4]])[0];H.dot(p[0],p[1],.85,'blue',.95)}
else for(const dx of[-1.8,1.6])H.line(R,T([[hx+dx-.9,hy],[hx+dx+.9,hy+.3]]),'blue',.6,{tone:.85,amp:0});
for(const dx of[5,8]){const p=T([[cx+dx,cy+2]])[0];const pw=ell(p[0],p[1],2.2,1.3,10);
H.fill(pw,'paper',1);H.tint(pw,'sun',.2);H.outline(R,pw,'blue',.6,{tone:.8,amp:0})}}

/* ---- props the figures carry. prop() runs inside the figure's own draw. ---- */
function leadProp(H,R,pts,u){
LEAD.near=pts.nearHand;
if(pencilInHand(u)){const [x,y]=pts.nearHand;
H.line(R,[[x-1.8,y-4.5],[x+2.4,y+5.2]],'sun',1.7,{tone:.85,amp:0});
H.line(R,[[x+1.9,y+4],[x+2.7,y+6.4]],'blue',1.1,{tone:.95,amp:0})}}
function thirdProp(H,R,pts,u,w){
THIRD.near=pts.nearHand;
if(w<.4){const [x,y]=pts.nearHand;H.line(R,[[x+1.2,y-4],[x-2.6,y+5.4]],'blue',1.3,{tone:.95,amp:0})}}
/* the sleeper: blanket, the back of her head, headphones, the phone still playing */
function sleeperProp(H,R,pts,u,w){
const D=pts.D,b=pts.b,br=.5-.5*Math.cos(TAU*u/4),kn=w*3.2;
const top=[[-2.6,4.5],[-3.6,-1],[-5.2-kn,-9],[-4.6-kn*.6,-13],[-7.4,-18.5],[-5.6-br*.9,-24],[-6.4-br*1.1,-29],[-5.2,-33.4]];
const hem=[[-1.2,-34.8],[3.2,-34.2],[6.8,-31],[7.6,-23],[7.9,-14],[7.2,-6],[6.2,1.5],[3.6,5.6],[.2,6.2]];
const Bk=loop(top.concat(hem),2);
D.fill(Bk,['sun',.62,'coral',.12]);
H.clip(D.P(Bk),()=>{
for(const x of[-2.5,1.2,4.8])D.line([[x,6],[x+.4,-35]],'coral',.9,.55);
for(const y of[-4,-12,-20,-28])D.line([[-9,y],[12,y]],'coral',.9,.45)});
D.line([[-5.4,-30],[3,-33.8]],'blue',.7,.6);D.line([[-6.8,-18.5],[-1,-17]],'blue',.6,.45);                 // the fold at her shoulder
const hx=b.head[0],hy=b.head[1],hr=6.4;
D.oval(hx,hy,hr*1.02,hr*1.07,SLEEPER_HAIR,{w:.8});
D.line(arcPts(hx,hy,hr+1.3,hr+1.5,Math.PI*1.08,Math.PI*1.92,10),'blue',1.9,.92);
D.oval(hx+hr*.95,hy+.8,2.3,3.3,['blue',.85]);
D.oval(hx-hr*.95,hy+.8,1.9,3.0,['coral',.6,'blue',.3]);
D.line(curve([[hx+hr*.9,hy+3.5],[hx+6,hy+10],[6.5,-24],[5,-19]],2),'blue',.6,.8);
D.fill([[3.2,-21],[7.2,-21.6],[7.6,-15.6],[3.6,-15]],['blue',.85]);
D.fill([[3.9,-20.3],[6.7,-20.7],[7,-16.4],[4.2,-16]],['teal',.55],{line:false})}

