const G=[lbP(HH,LB.i0+.1,LB.j0+.1,.004),lbP(HH,LB.i1-.08,LB.j0+.1,.004),lbP(HH,LB.i1-.08,LB.j1-.1,.004),lbP(HH,LB.i0+.1,LB.j1-.1,.004)];
