HH.clip(cone,()=>HH.light(...centroid(cone),24,20,.12));HH.tint(cone,'sun',.10);
HH.clip(this.lbGlass?[lbP(HH,LB.i0,LB.j0),lbP(HH,LB.i1,LB.j0),lbP(HH,LB.i1,LB.j1),lbP(HH,LB.i0,LB.j1)]:cone,
()=>{HH.light(pool[0],pool[1],30,14,.30);HH.glow(pool[0],pool[1],32,15,'sun',.28)});
