/* ======================== OVER — baked, always in front ================== */
over(H,R){
const [px,py]=H.p(11.05,10.95,0);
shadowAt(H,px+4,py+2,22,9,.22);
const pot=[[px-17,py-26],[px+17,py-26],[px+12,py],[px-12,py]];
H.fill(pot,'coral',.62);H.tint([[px,py-26],[px+17,py-26],[px+12,py],[px,py]],'blue',.30);
H.outline(R,pot,'blue',1.3,{amp:.25});
H.line(R,[[px-17,py-21],[px+17,py-21]],'blue',1,{tone:.6,amp:.2});
const PR=streamOf('seoul','bigplant');
for(let k=0;k<13;k++){
const a=-Math.PI/2+rd(PR,-1.25,1.25),L=rd(PR,26,62);
const tip=[px+Math.cos(a)*L,py-26+Math.sin(a)*L];
const mid=[lerp(px,tip[0],.5)+rd(PR,-9,9),lerp(py-26,tip[1],.5)+rd(PR,-6,6)];
const leaf=loop([[px,py-26],[mid[0]-7,mid[1]],tip,[mid[0]+7,mid[1]]],2);
H.fill(leaf,'teal',rd(PR,.50,.85));H.tint(leaf,'blue',.18);H.outline(R,leaf,'blue',1,{tone:.85,amp:.25})}
},

